render_assets.css:
:root {
      --paper: #ffffff;
      --paper-strong: #ffffff;
      --ink: #151515;
      --ink-soft: #4d4d4d;
      --muted: #6a6e73;
      --rule: #d2d2d2;
      --rule-dark: #9c9c9c;
      --purple: #c9190b;
      --purple-soft: #faeae8;
      --coral: #ee0000;
      --coral-soft: #fff0f0;
      --green: #3e8635;
      --amber: #f0ab00;
      --navy: #151515;
      --toolbar: 52px;
      --ticker-speed: 120s;
      --sans: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
      --serif: var(--sans);
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; overflow-x: clip; background: #f3f3f3; }
    body { margin: 0; overflow-x: clip; color: var(--ink); background: #f3f3f3; font-family: var(--sans); }
    button, input { font: inherit; }
    a { color: inherit; }
    [hidden] { display: none !important; }

    .studio-toolbar {
      position: sticky;
      top: 0;
      z-index: 80;
      min-height: var(--toolbar);
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 18px;
      color: #fff;
      background: var(--navy);
      border-bottom: 3px solid var(--coral);
      overflow-x: auto;
      white-space: nowrap;
    }
    .studio-toolbar button {
      min-height: 34px;
      padding: 7px 11px;
      border: 1px solid #52617c;
      color: #fff;
      background: transparent;
      font-size: 11px;
      font-weight: 800;
      letter-spacing: .06em;
      text-transform: uppercase;
      cursor: pointer;
    }
    .studio-toolbar button:hover,
    .studio-toolbar button:focus-visible { border-color: #fff; outline: none; }
    .studio-toolbar button.primary { border-color: var(--coral); background: var(--coral); }
    .studio-toolbar button.is-active { border-color: #fff; background: #3c3c3c; }
    .studio-status {
      margin-left: auto;
      color: #cbd3e2;
      font-size: 10px;
      font-weight: 750;
      letter-spacing: .04em;
    }

    .memo {
      width: min(1440px, calc(100% - 48px));
      margin: 0 auto;
      padding: 0 0 48px;
      background: var(--paper);
      box-shadow: 0 0 0 1px #e5e5e5;
    }

    .brand-band {
      min-height: 92px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 24px;
      padding: 0 18px;
      border-bottom: 4px solid var(--coral);
    }
    .brand-lockup { display: flex; align-items: center; gap: 16px; min-width: 0; }
    .client-mark {
      width: 118px;
      height: 64px;
      flex: 0 0 auto;
      border-right: 1px solid var(--rule);
      padding-right: 16px;
    }
    .gtm-mark { width: 92px; height: 58px; flex: 0 0 auto; }
    .logo-slot {
      position: relative;
      display: grid;
      place-items: center;
      color: var(--purple);
      background: #fff;
      overflow: hidden;
      user-select: none;
    }
    .logo-slot img { width: 100%; height: 100%; object-fit: contain; display: block; }
    .logo-slot img, .logo-slot .logo-fallback { grid-area: 1 / 1; }
    .logo-slot .logo-fallback {
      display: grid;
      width: 100%;
      height: 100%;
      place-items: center;
      padding: 3px;
      color: currentColor;
      font-family: var(--sans);
      font-size: 10px;
      font-weight: 900;
      letter-spacing: .04em;
      line-height: 1;
      text-align: center;
    }
    .logo-slot.has-image .logo-fallback { display: none; }
    .brand-copy strong {
      display: block;
      font-size: 14px;
      letter-spacing: .16em;
      text-transform: uppercase;
    }
    .brand-copy span { display: block; margin-top: 4px; color: var(--muted); font-size: 12px; }

    .ticker {
      width: 100%;
      height: 38px;
      overflow: hidden;
      color: #fff;
      background: var(--ink);
      border-bottom: 2px solid var(--coral);
    }
    .ticker-track {
      width: max-content;
      height: 100%;
      display: flex;
      align-items: center;
      animation: ticker var(--ticker-speed) linear infinite;
      will-change: transform;
    }
    .ticker:hover .ticker-track,
    .ticker:focus-within .ticker-track { animation-play-state: paused; }
    .ticker-group { min-width: 100vw; display: flex; align-items: center; gap: 44px; padding: 0 28px; }
    .ticker a {
      color: #fff;
      text-decoration: none;
      font-size: 10px;
      font-weight: 800;
      letter-spacing: .1em;
      text-transform: uppercase;
    }
    .ticker a::before { content: ""; display: inline-block; width: 6px; height: 6px; margin-right: 10px; border-radius: 50%; background: var(--coral); vertical-align: 1px; }
    .ticker a:hover, .ticker a:focus-visible { color: #fff; outline: none; text-decoration: underline; text-decoration-color: var(--coral); }
    @keyframes ticker { to { transform: translateX(-50%); } }

    .memo-title {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 32px;
      align-items: start;
      padding: 34px 4px 26px;
    }
    .memo-title h1 {
      max-width: 1250px;
      margin: 0;
      font-family: var(--serif);
      font-size: clamp(44px, 4.7vw, 68px);
      line-height: .98;
      font-weight: 500;
      letter-spacing: -.045em;
    }
    .memo-title p {
      margin: 10px 0 0;
      color: var(--ink-soft);
      font-family: var(--serif);
      font-size: clamp(20px, 2.2vw, 31px);
      font-style: italic;
    }
    .edition-meta {
      display: grid;
      justify-items: end;
      gap: 9px;
      padding: 14px 0 0;
      border: 0;
      color: inherit;
      background: transparent;
      text-align: right;
      cursor: pointer;
    }
    .edition-meta:hover time, .edition-meta:focus-visible time { color: var(--purple); }
    .edition-meta:focus-visible { outline: 2px solid var(--purple); outline-offset: 4px; }
    .edition-meta time { font-size: 12px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; }
    .edition-meta span { color: var(--muted); font-size: 10px; letter-spacing: .1em; text-transform: uppercase; }

    .decision-board {
      display: grid;
      grid-template-columns: minmax(300px, .34fr) minmax(0, .66fr);
      border-bottom: 2px solid var(--purple);
      padding-bottom: 30px;
    }
    .market-proof {
      min-height: 280px;
      padding: 4px 36px 0 6px;
      border-right: 1px solid var(--rule-dark);
    }
    .market-proof .money {
      display: block;
      margin: 0;
      padding: 0;
      border: 0;
      color: var(--ink);
      background: transparent;
      font-family: var(--serif);
      font-size: clamp(74px, 9.3vw, 132px);
      line-height: .9;
      letter-spacing: -.055em;
      cursor: pointer;
    }
    .market-proof .money.range { max-width: 100%; white-space: normal; font-size: clamp(29px, 3.2vw, 46px); line-height: .98; overflow-wrap: anywhere; }
    .record-id {
      color: var(--purple);
      font-family: ui-monospace, SFMono-Regular, Menlo, monospace !important;
      font-size: 15px !important;
      font-weight: 800 !important;
      letter-spacing: -.02em;
    }
    .record-type {
      display: block;
      margin-bottom: 8px;
      color: var(--coral);
      font-size: 9px;
      font-weight: 850;
      letter-spacing: .1em;
      text-transform: uppercase;
    }
    .record-facts { display: flex; flex-wrap: wrap; gap: 7px 14px; margin-top: 15px; color: var(--ink-soft); font-size: 10px; line-height: 1.4; }
    .record-facts a { padding-right: 14px; border-right: 1px solid var(--rule); text-decoration: none; }
    .record-facts a:last-child { padding-right: 0; border-right: 0; }
    .record-facts a:hover, .record-facts a:focus-visible { color: var(--purple); text-decoration: underline; outline: none; }
    .market-proof h2 { margin: 14px 0 0; font-family: var(--serif); font-size: 29px; line-height: 1; }
    .market-proof p { max-width: 420px; margin: 13px 0 0; color: var(--ink-soft); font-family: var(--serif); font-size: 17px; line-height: 1.4; }
    .source-line { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 22px; color: var(--muted); font-size: 10px; }
    .source-line a { text-underline-offset: 3px; }

    .decision-list { padding-left: 38px; }
    .decision-row {
      width: 100%;
      display: grid;
      grid-template-columns: 190px minmax(0, 1fr) auto;
      gap: 22px;
      align-items: center;
      padding: 17px 0;
      border: 0;
      border-bottom: 1px solid var(--rule);
      color: var(--ink);
      background: transparent;
      text-align: left;
      cursor: pointer;
    }
    .decision-row:last-child { border-bottom: 0; }
    .decision-row strong { font-family: var(--serif); font-size: 25px; font-weight: 600; }
    .decision-row p { margin: 0; color: var(--ink); font-family: var(--serif); font-size: 16px; line-height: 1.35; }
    .decision-row .action { color: var(--purple); font-size: 10px; font-weight: 850; letter-spacing: .08em; text-transform: uppercase; }
    .decision-row.compete .action { color: var(--coral); }
    .decision-row:hover p, .decision-row:focus-visible p { color: var(--purple); }
    .decision-row:focus-visible { outline: 2px solid var(--purple); outline-offset: 4px; }

    .pursuit-lead { padding-top: 2px; }
    .pursuit-lead .record-type { color: var(--purple); }
    .pursuit-lead .money.range {
      margin-top: 8px;
      font-size: clamp(34px, 3.5vw, 50px);
      line-height: .96;
      letter-spacing: -.045em;
      overflow-wrap: normal;
    }
    .pursuit-lead .range-line { display: block; white-space: nowrap; }
    .pursuit-lead .range-divider { display: block; line-height: .72; text-align: center; }
    .motion-label {
      display: block;
      margin-top: 20px;
      color: var(--purple);
      font-family: var(--serif);
      font-size: 28px;
      font-weight: 700;
      line-height: 1;
    }
    .lead-facts { margin-top: 17px; border-top: 1px solid var(--rule-dark); }
    .lead-fact {
      display: grid;
      grid-template-columns: 122px minmax(0, 1fr);
      gap: 14px;
      padding: 9px 0;
      border-bottom: 1px solid var(--rule);
      align-items: baseline;
    }
    .lead-fact span {
      color: var(--ink);
      font-size: 9px;
      font-weight: 850;
      letter-spacing: .09em;
      text-transform: uppercase;
    }
    .lead-fact strong, .lead-fact a {
      color: var(--ink);
      font-family: var(--serif);
      font-size: 16px;
      font-weight: 500;
      text-decoration-color: #b8aedf;
      text-underline-offset: 3px;
    }
    .lead-fact a:hover, .lead-fact a:focus-visible { color: var(--purple); outline: none; }
    .pursuit-tape { padding-left: 34px; }
    .pursuit-tape h2 { margin: 0 0 12px; font-family: var(--serif); font-size: 28px; font-weight: 600; }
    .pursuit-columns, .pursuit-row {
      display: grid;
      grid-template-columns: 34px 74px 136px 116px minmax(105px, 1fr) 92px minmax(115px, 1fr);
      gap: 10px;
      align-items: center;
    }
    .pursuit-columns {
      min-height: 31px;
      border-bottom: 1px solid var(--ink);
      color: var(--ink);
      font-size: 8px;
      font-weight: 850;
      letter-spacing: .08em;
      text-transform: uppercase;
    }
    .pursuit-columns span:first-child { grid-column: 1 / 3; }
    .pursuit-row {
      width: 100%;
      min-height: 82px;
      padding: 11px 0;
      border: 0;
      border-bottom: 1px solid var(--rule);
      color: var(--ink);
      background: transparent;
      text-align: left;
      cursor: pointer;
    }
    .pursuit-row:last-child { border-bottom-color: var(--ink); }
    .pursuit-row:hover, .pursuit-row:focus-visible { color: var(--purple); outline: none; background: #f7f4ff; }
    .pursuit-rank { font-family: var(--serif); font-size: 38px; font-weight: 400; }
    .pursuit-motion { color: var(--purple); font-family: var(--serif); font-size: 17px; font-weight: 700; }
    .pursuit-row.expand .pursuit-motion { color: var(--coral); }
    .pursuit-value { font-family: var(--serif); font-size: 15px; font-weight: 700; line-height: 1.15; letter-spacing: -.01em; }
    .pursuit-id { color: var(--purple); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 10px; font-weight: 800; overflow-wrap: anywhere; }
    .pursuit-name, .pursuit-target, .pursuit-ask { font-family: var(--serif); font-size: 13px; line-height: 1.3; }

    .named-routes { scroll-margin-top: 100px; padding: 12px 6px 8px; }
    .named-routes-head { display: flex; align-items: baseline; justify-content: space-between; gap: 24px; margin-bottom: 8px; }
    .named-routes h2 { margin: 0; font-family: var(--serif); font-size: 27px; font-weight: 600; }
    .named-routes-head p { margin: 0; color: var(--muted); font-size: 10px; }
    .route-table td { padding-top: 10px; padding-bottom: 10px; }
    .route-table .route-id { color: var(--purple); font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-weight: 800; }
    .route-table .route-ask { max-width: 280px; }
    .route-table .target-name { display: block; font-family: var(--serif); font-size: 15px; }
    .route-table .target-email { display: block; margin-top: 3px; color: var(--purple); font-family: var(--sans); font-size: 9px; font-weight: 750; }

    .two-ledgers { display: grid; grid-template-columns: 1fr 1fr; gap: 34px; padding: 26px 6px 8px; }
    .ledger + .ledger { border-left: 1px solid var(--rule-dark); padding-left: 34px; }
    .ledger h2 { margin: 0 0 11px; font-family: var(--serif); font-size: 27px; }
    .table-wrap { overflow-x: auto; }
    table { width: 100%; border-collapse: collapse; font-family: var(--serif); font-size: 13px; }
    th { padding: 7px 8px; color: var(--ink); font-family: var(--sans); font-size: 9px; letter-spacing: .08em; text-align: left; text-transform: uppercase; border-bottom: 1px solid var(--rule-dark); }
    td { padding: 9px 8px; border-bottom: 1px solid var(--rule); vertical-align: middle; }
    tbody tr:hover { background: #f4f1fb; }
    .agency-cell { display: flex; align-items: center; gap: 9px; min-width: 150px; }
    .seal-slot, .partner-slot {
      width: 34px;
      height: 34px;
      flex: 0 0 auto;
      border: 1px solid var(--rule);
      border-radius: 50%;
      color: var(--ink-soft);
      font-family: var(--sans);
      font-size: 9px;
      font-weight: 850;
      letter-spacing: .03em;
    }
    .partner-slot { width: 76px; height: 38px; border-radius: 4px; }
    [data-logo-slot-id="prime-fcn"] img,
    [data-logo-slot-id="prime-swish"] img { object-fit: fill; transform: none; }
    .logo-slot.is-unmatched {
      border-style: dashed;
      color: var(--coral);
      font-size: 7px;
      line-height: 1.15;
      text-align: center;
      text-transform: uppercase;
    }
    .motion-shape { color: var(--purple); font-weight: 700; }
    .motion-compete { color: var(--coral); font-weight: 700; }
    .source-link { color: var(--purple); font-family: var(--sans); font-size: 10px; font-weight: 800; text-underline-offset: 3px; }
    .evidence-value { color: inherit; font-weight: inherit; text-decoration: underline; text-decoration-color: #b8aedf; text-underline-offset: 3px; }
    .evidence-value:hover, .evidence-value:focus-visible { color: var(--purple); outline: none; text-decoration-color: currentColor; }
    .claim-button {
      display: block;
      max-width: 930px;
      margin: 0;
      padding: 0;
      border: 0;
      color: inherit;
      background: transparent;
      font-family: var(--serif);
      font-size: clamp(34px, 4vw, 55px);
      line-height: 1.02;
      font-weight: 500;
      letter-spacing: -.025em;
      text-align: left;
      cursor: pointer;
    }
    .claim-button:hover, .claim-button:focus-visible { color: var(--purple); outline: none; text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 5px; }

    .pipeline-nav {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 12px;
      margin: 25px 6px 0;
      padding: 15px 0 5px;
      border-top: 1px solid var(--rule-dark);
      color: var(--ink-soft);
      font-family: var(--serif);
      font-size: 13px;
    }
    .pipeline-nav strong { margin-right: 10px; color: var(--ink); font-family: var(--sans); font-size: 10px; letter-spacing: .09em; text-transform: uppercase; }
    .pipeline-nav a { text-decoration: none; }
    .pipeline-nav a:hover, .pipeline-nav a:focus-visible { color: var(--purple); outline: none; text-decoration: underline; }
    .pipeline-nav .show-work-link { margin-left: auto; border: 0; color: var(--coral); background: transparent; font-family: var(--serif); font-size: 17px; cursor: pointer; }
    body:has(.drawer-scrim.open) .pipeline-nav .show-work-link {
      position: fixed;
      top: 24px;
      right: 76px;
      z-index: 102;
      margin: 0;
      padding: 8px 11px;
      color: var(--ink);
      background: var(--paper-strong);
      border: 1px solid var(--rule-dark);
      font-family: var(--sans);
      font-size: 10px;
      font-weight: 850;
      letter-spacing: .04em;
      text-transform: uppercase;
    }

    .report-section { scroll-margin-top: 100px; padding: 52px 6px 18px; }
    .section-head { display: grid; grid-template-columns: 190px minmax(0, 1fr); gap: 32px; align-items: start; margin-bottom: 24px; }
    .section-index { color: var(--coral); font-size: 10px; font-weight: 850; letter-spacing: .12em; text-transform: uppercase; }
    .section-head h2 { max-width: 930px; margin: 0; font-family: var(--serif); font-size: clamp(34px, 4vw, 55px); line-height: 1.02; font-weight: 500; letter-spacing: -.025em; }
    .section-head p { max-width: 830px; margin: 12px 0 0; color: var(--ink-soft); font-family: var(--serif); font-size: 17px; line-height: 1.45; }

    .data-ledger { border-top: 2px solid var(--ink); border-bottom: 1px solid var(--ink); }
    .data-row {
      display: grid;
      grid-template-columns: minmax(220px, 1.4fr) minmax(150px, .8fr) minmax(160px, 1fr) minmax(180px, 1.1fr) 100px;
      align-items: center;
      min-height: 70px;
      border-bottom: 1px solid var(--rule);
    }
    .data-row:last-child { border-bottom: 0; }
    .data-row > * { padding: 11px 14px; }
    .data-row .name { display: flex; align-items: center; gap: 11px; font-family: var(--serif); font-size: 16px; }
    .data-row .amount { font-family: var(--serif); font-size: 21px; font-weight: 700; }
    .data-row .sub { color: var(--muted); font-size: 11px; line-height: 1.4; }
    .work-button { border: 0; color: var(--purple); background: transparent; font-size: 10px; font-weight: 850; text-decoration: underline; text-underline-offset: 3px; cursor: pointer; }

    .future-strip { display: grid; grid-template-columns: repeat(4, 1fr); border-top: 2px solid var(--ink); border-bottom: 1px solid var(--ink); }
    .future-item { min-height: 150px; padding: 21px 20px; border-right: 1px solid var(--rule); }
    .future-item:last-child { border-right: 0; }
    .future-item > a { display: block; color: inherit; text-decoration: none; }
    .future-item > a:hover strong, .future-item > a:focus-visible strong { color: var(--purple); text-decoration: underline; }
    .future-item > a:focus-visible { outline: 2px solid var(--purple); outline-offset: 4px; }
    .future-item time { display: block; color: var(--coral); font-size: 10px; font-weight: 850; letter-spacing: .08em; text-transform: uppercase; }
    .future-item strong { display: block; margin-top: 15px; font-family: var(--serif); font-size: 21px; }
    .future-item p { margin: 9px 0 0; color: var(--ink-soft); font-size: 12px; line-height: 1.45; }

    .vocabulary { display: grid; grid-template-columns: 1fr 1fr; border-top: 2px solid var(--ink); border-bottom: 1px solid var(--ink); }
    .term { display: grid; grid-template-columns: 110px minmax(0, 1fr); gap: 16px; padding: 18px 14px; border-bottom: 1px solid var(--rule); }
    .term:nth-child(odd) { border-right: 1px solid var(--rule); }
    .term:nth-last-child(-n+2) { border-bottom: 0; }
    .term strong { color: var(--purple); font-size: 10px; letter-spacing: .08em; text-transform: uppercase; }
    .term p { margin: 0; color: var(--ink-soft); font-family: var(--serif); font-size: 15px; line-height: 1.4; }

    .report-foot {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 30px;
      align-items: end;
      margin: 45px 6px 0;
      padding-top: 18px;
      border-top: 1px solid var(--rule-dark);
      color: var(--muted);
      font-size: 10px;
      line-height: 1.5;
    }
    .report-foot img { width: 70px; height: 42px; object-fit: contain; }

    .drawer-scrim {
      position: fixed;
      inset: 0;
      z-index: 100;
      display: grid;
      justify-items: end;
      background: rgba(9, 22, 47, .28);
      opacity: 0;
      visibility: hidden;
      transition: opacity .2s ease, visibility .2s ease;
    }
    .drawer-scrim.open { opacity: 1; visibility: visible; }
    .work-drawer {
      width: min(540px, calc(100vw - 24px));
      height: 100%;
      display: grid;
      grid-template-rows: auto 1fr auto;
      color: var(--ink);
      background: var(--paper-strong);
      border-left: 4px solid var(--purple);
      transform: translateX(100%);
      transition: transform .24s ease;
    }
    .drawer-scrim.open .work-drawer { transform: translateX(0); }
    .drawer-head, .drawer-foot { padding: 24px 26px; border-bottom: 1px solid var(--rule); }
    .drawer-head { display: flex; justify-content: space-between; gap: 18px; align-items: start; }
    .drawer-head span { color: var(--coral); font-size: 9px; font-weight: 850; letter-spacing: .1em; text-transform: uppercase; }
    .drawer-head h2 { margin: 7px 0 0; font-family: var(--serif); font-size: 32px; line-height: 1.05; }
